      "type" : "number",
      "default" : 0.0000000000000000E+000,
      "description" : "Base Q value for normalization. Default is zero, meaning the peak will be used.",
      "units" : "kvar",
      "title" : "QBase",
      "$dssPropertyIndex" : 18,
      "$dssPropertyOrder" : 15
